-- Converts the account, common, player and log databases to utf8mb4. Text goes through binary
-- columns so stored UTF-8 bytes are kept; values that are not valid UTF-8 are either UTF-8 cut off
-- mid-character (trimmed) or legacy EUC-KR (converted). Proto names widen to the 63 bytes the
-- server uses; proto names that are latin1 mojibake of EUC-KR are repaired. Run once against an existing volume: mariadb -uroot -p < migrate-utf8mb4.sql
SET SESSION sql_mode='NO_ENGINE_SUBSTITUTION';

ALTER DATABASE `account` CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_as_ci;
ALTER DATABASE `common` CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_as_ci;
ALTER DATABASE `player` CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_as_ci;
ALTER DATABASE `log` CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_as_ci;

ALTER TABLE `account`.`account` MODIFY `login` varbinary(30) NOT NULL DEFAULT '', MODIFY `password` varbinary(45) NOT NULL DEFAULT '', MODIFY `social_id` varbinary(13) NOT NULL DEFAULT '', MODIFY `email` varbinary(64) NOT NULL DEFAULT '', MODIFY `status` varbinary(8) NOT NULL DEFAULT 'OK', MODIFY `securitycode` varbinary(192) NULL DEFAULT '', MODIFY `channel_company` varbinary(30) NOT NULL DEFAULT '', MODIFY `ip` varbinary(255) NULL DEFAULT NULL;
UPDATE `account`.`account` SET `login` = LEFT(`login`, LENGTH(`login`) - 1) WHERE `login` IS NOT NULL AND CAST(CONVERT(`login` USING utf8mb4) AS BINARY) <> `login` AND LENGTH(`login`) > 1 AND CAST(CONVERT(LEFT(`login`, LENGTH(`login`) - 1) USING utf8mb4) AS BINARY) = LEFT(`login`, LENGTH(`login`) - 1);
UPDATE `account`.`account` SET `login` = LEFT(`login`, LENGTH(`login`) - 2) WHERE `login` IS NOT NULL AND CAST(CONVERT(`login` USING utf8mb4) AS BINARY) <> `login` AND LENGTH(`login`) > 2 AND CAST(CONVERT(LEFT(`login`, LENGTH(`login`) - 2) USING utf8mb4) AS BINARY) = LEFT(`login`, LENGTH(`login`) - 2);
UPDATE `account`.`account` SET `login` = LEFT(`login`, LENGTH(`login`) - 3) WHERE `login` IS NOT NULL AND CAST(CONVERT(`login` USING utf8mb4) AS BINARY) <> `login` AND LENGTH(`login`) > 3 AND CAST(CONVERT(LEFT(`login`, LENGTH(`login`) - 3) USING utf8mb4) AS BINARY) = LEFT(`login`, LENGTH(`login`) - 3);
UPDATE `account`.`account` SET `login` = CONVERT(CONVERT(`login` USING euckr) USING utf8mb4) WHERE `login` IS NOT NULL AND CAST(CONVERT(`login` USING utf8mb4) AS BINARY) <> `login`;
UPDATE `account`.`account` SET `password` = LEFT(`password`, LENGTH(`password`) - 1) WHERE `password` IS NOT NULL AND CAST(CONVERT(`password` USING utf8mb4) AS BINARY) <> `password` AND LENGTH(`password`) > 1 AND CAST(CONVERT(LEFT(`password`, LENGTH(`password`) - 1) USING utf8mb4) AS BINARY) = LEFT(`password`, LENGTH(`password`) - 1);
UPDATE `account`.`account` SET `password` = LEFT(`password`, LENGTH(`password`) - 2) WHERE `password` IS NOT NULL AND CAST(CONVERT(`password` USING utf8mb4) AS BINARY) <> `password` AND LENGTH(`password`) > 2 AND CAST(CONVERT(LEFT(`password`, LENGTH(`password`) - 2) USING utf8mb4) AS BINARY) = LEFT(`password`, LENGTH(`password`) - 2);
